/**
 * Parse a config value that is expected to represent a positive integer.
 *
 * Returns the parsed integer when the (trimmed) value represents a positive whole number, otherwise
 * `null` (this includes values like '0', 'false', 'null', 'undefined', '' and negative numbers).
 */
export const parsePositiveIntegerConfigValue = (
  value: string | null | undefined
): number | null => {
  if (value == null) {
    return null;
  }

  const trimmed = value.trim();

  if (trimmed === '') {
    return null;
  }

  const parsed = Number(trimmed);

  if (!Number.isInteger(parsed) || parsed <= 0) {
    return null;
  }

  return parsed;
};

/**
 * Parse a value that is expected to be an ISO date string into a `Date`.
 *
 * Returns `null` for non-strings, empty strings and strings that cannot be parsed into a valid date.
 */
export const parseReleaseTime = (value: unknown): Date | null => {
  if (typeof value !== 'string' || value.trim() === '') {
    return null;
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date;
};

/**
 * Parse a value that is expected to be a map of package version -> release time (as returned by
 * package registries).
 *
 * Returns a plain object mapping string keys to string values, or `null` when the value is not a
 * plain object (e.g. a string, an array or nullish). Entries with empty string values are omitted.
 */
export const parsePackageTimeMap = (value: unknown): Record<string, string> | null => {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }

  const result: Record<string, string> = {};

  for (const [key, entry] of Object.entries(value as Record<string, unknown>)) {
    if (typeof entry === 'string' && entry !== '') {
      result[key] = entry;
    }
  }

  return result;
};

/** Compute the age in whole (floored) minutes between a reference date and a published-at date. */
export const getAgeInMinutes = (referenceDate: Date, publishedAt: Date): number => {
  return Math.floor((referenceDate.getTime() - publishedAt.getTime()) / (1000 * 60));
};

/**
