 * @param versionToReleaseTime Map of version -> ISO release time.
 * @param minimumAgeGateInMinutes Minimum age (in minutes) a release must have.
 * @param referenceTime Reference point in time to measure the age against (defaults to now).
 * @returns The latest qualifying stable version, or `null` when none qualifies.
 */
export const getLatestStableVersionAdheringToMinimumAgeGate = (
  versionToReleaseTime: Record<string, string>,
  minimumAgeGateInMinutes: number,
  referenceTime: Date = new Date()
): string | null => {
  const qualifyingVersions = Object.entries(versionToReleaseTime)
    .filter(([version]) => valid(version) !== null && prerelease(version) === null)
    .filter(([, releaseTime]) => {
      const releaseDate = parseReleaseTime(releaseTime);

