 */
export const hasStorybookMinimumAgeExclusions = (configuredPatterns: string[]): boolean => {
  return CORE_STORYBOOK_MINIMUM_AGE_PATTERNS.every((corePattern) =>
    configuredPatterns.some((pattern) => globToRegExp(pattern).test(corePattern))
